168	// ─── Link / unlink bookings ────────────────────────────────────────────────────
169	
170	export async function linkBookingAction(
171	  projectId: string,
172	  bookingId: string
173	): Promise<ActionResult<void>> {
174	  const auth = await getAuthenticatedUser()
175	  if (!auth) return { ok: false, error: 'Not authenticated' }
176	  if (auth.role === 'guest_artist') return { ok: false, error: 'Insufficient permissions' }
177	
178	  try {
179	    await linkBookingToProject(auth.studioId, bookingId, projectId)
180	    revalidatePath('/projects')
181	    revalidatePath(`/projects/${projectId}`)
182	    revalidatePath('/bookings')
183	    return { ok: true, data: undefined }
184	  } catch (err) {
185	    logger.error({ err, projectId, bookingId }, 'linkBookingAction failed')
186	    return { ok: false, error: 'Failed to link booking' }
187	  }
188	}
