190	export async function unlinkBookingAction(
191	  projectId: string,
192	  bookingId: string
193	): Promise<ActionResult<void>> {
194	  const auth = await getAuthenticatedUser()
195	  if (!auth) return { ok: false, error: 'Not authenticated' }
196	  if (!canAdmin(auth.role as ReadRole)) return { ok: false, error: 'Only owners and admins can unlink sessions' }
197	
198	  try {
199	    await unlinkBookingFromProject(auth.studioId, bookingId)
200	    revalidatePath('/projects')
201	    revalidatePath(`/projects/${projectId}`)
202	    revalidatePath('/bookings')
