297	// ─── Progress photos ──────────────────────────────────────────────────────────
298	
299	export async function addProgressPhotoAction(
300	  projectId: string,
301	  formData: FormData
302	): Promise<ActionResult<{ id: string }>> {
303	  const auth = await getAuthenticatedUser()
304	  if (!auth) return { ok: false, error: 'Not authenticated' }
305	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
306	
307	  const supabase = await createClient()
308	
309	  const file = formData.get('file') as File | null
310	  if (!file) return { ok: false, error: 'No file provided' }
311	
312	  const fileExt = file.name.split('.').pop() ?? 'jpg'
313	  const kind = (formData.get('kind') as string) || 'progress'
314	  const storagePath = `${auth.studioId}/${projectId}/${kind}/${Date.now()}.${fileExt}`
315	
316	  const { error: uploadError } = await supabase.storage
317	    .from('project-photos')
318	    .upload(storagePath, file, { upsert: false })
319	
320	  if (uploadError) {
321	    logger.error({ uploadError, projectId }, 'addProgressPhotoAction upload failed')
322	    return { ok: false, error: 'Failed to upload photo' }
323	  }
324	
325	  const raw = {
326	    storagePath,
327	    kind: formData.get('kind'),
328	    takenAt: (formData.get('takenAt') as string) || undefined,
329	    bookingId: (formData.get('bookingId') as string) || undefined,
330	    caption: (formData.get('caption') as string) || undefined,
331	  }
332	
333	  const parsed = addProgressPhotoSchema.safeParse(raw)
334	  if (!parsed.success) {
335	    return { ok: false, error: 'Validation failed' }
336	  }
337	
338	  try {
339	    const photo = await addProgressPhoto(auth.studioId, projectId, parsed.data)
340	    revalidatePath(`/projects/${projectId}`)
341	    return { ok: true, data: { id: photo.id } }
342	  } catch (err) {
343	    logger.error({ err, projectId }, 'addProgressPhotoAction failed')
344	    return { ok: false, error: 'Failed to save photo' }
345	  }
346	}
