'use server'

import { revalidatePath } from 'next/cache'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { z } from 'zod'

type ActionResult<T = void> =
  | { ok: true; data: T }
  | { ok: false; error: string }

const quickCreateClientSchema = z.object({
  firstName: z.string().min(1, 'First name is required').max(100),
  lastName: z.string().max(100).optional(),
  phone: z.string().max(30).optional(),
  email: z.string().email('Invalid email').optional().or(z.literal('')),
})

/**
 * Minimal client creation for the inline "Create new client" dialog in the
 * New Project form. Full client creation lives at /clients/new.
 */
export async function quickCreateClientAction(
  formData: FormData
): Promise<ActionResult<{ id: string; label: string; email: string | null }>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }
  if (auth.role === 'guest_artist') return { ok: false, error: 'Insufficient permissions' }

  const raw = {
    firstName: formData.get('firstName'),
    lastName: formData.get('lastName') || undefined,
    phone: formData.get('phone') || undefined,
    email: formData.get('email') || undefined,
  }

  const parsed = quickCreateClientSchema.safeParse(raw)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
  }

  const supabase = await createClient()

  const { data, error } = await supabase
    .from('clients')
    .insert({
      studio_id: auth.studioId,
      first_name: parsed.data.firstName,
      last_name: parsed.data.lastName ?? null,
      phone: parsed.data.phone ?? null,
      email: parsed.data.email || null,
    })
    .select('id, first_name, last_name, email')
    .single()

  if (error || !data) {
    logger.error({ error, studioId: auth.studioId }, 'quickCreateClientAction failed')
    return { ok: false, error: 'Failed to create client' }
  }

  revalidatePath('/clients')

  const label = `${data.first_name}${data.last_name ? ` ${data.last_name}` : ''}`
  return { ok: true, data: { id: data.id, label, email: data.email } }
}

