'use client'

import { useState, useTransition, useMemo, useRef, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { ArrowRight, Check, ChevronDown, Info, Loader2, Plus, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import { MoneyInput } from '@/components/ui/money-input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogFooter,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from '@/components/ui/card'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import { Switch } from '@/components/ui/switch'
import { FileDropzone } from '@/components/ui/file-dropzone'
import { Tooltip } from '@/components/ui/tooltip'
import { ComboBox } from '@/components/ui/combobox'
import { Badge } from '@/components/ui/badge'
import { cn } from '@/lib/utils'
import { createProjectAction } from '@/app/(app)/projects/actions'
import { quickCreateClientAction } from '@/app/(app)/clients/actions'
import {
  PROJECT_STYLES,
  PLACEMENT_PRESETS,
  PROJECT_SIZE_VALUES,
  PROJECT_COLOR_MODE_VALUES,
  DEPOSIT_APPLY_RULE_VALUES,
  type ProjectSize,
  type ProjectColorMode,
  type DepositApplyRule,
} from '@/lib/projects/schemas'
import { addReferenceAction } from '@/app/(app)/projects/actions'
import { logger } from '@/lib/logger'
import type { ComboBoxOption } from '@/components/ui/combobox'

// ─── Constants ────────────────────────────────────────────────────────────────

const STYLE_LABELS: Record<string, string> = {
  traditional: 'Traditional',
  neo_traditional: 'Neo-traditional',
  japanese: 'Japanese (Irezumi)',
  realism: 'Realism',
  black_and_grey: 'Black & Grey',
  fine_line: 'Fine line',
  blackwork: 'Blackwork',
  dotwork: 'Dotwork',
  geometric: 'Geometric',
  watercolor: 'Watercolor',
  tribal: 'Tribal',
  lettering: 'Lettering',
  portrait: 'Portrait',
  biomech: 'Biomech',
  custom: 'Custom',
}

const SIZE_LABELS: Record<ProjectSize, string> = {
  small: 'Small (<10cm)',
  medium: 'Medium (10–20cm)',
  large: 'Large (20–40cm)',
  extra_large: 'Extra large (40cm+)',
  full_sleeve: 'Full sleeve',
  full_back: 'Full back',
}

const COLOR_MODE_LABELS: Record<ProjectColorMode, string> = {
  color: 'Color',
  black_and_grey: 'Black & Grey',
  both: 'Both',
}

const DEPOSIT_RULE_LABELS: Record<DepositApplyRule, { label: string; desc: string }> = {
  last_session: { label: 'Last session', desc: 'Applied as credit on the final session' },
  split_evenly: { label: 'Split evenly', desc: 'Divided equally across all sessions' },
  manual: { label: 'Manual', desc: 'You allocate manually per session' },
}

const IMAGE_ACCEPT = { 'image/*': ['.jpg', '.jpeg', '.png', '.webp', '.gif'] }
const DRAFT_KEY_PREFIX = 'inkos:project-draft:'

// ─── Types ────────────────────────────────────────────────────────────────────

interface Artist {
  id: string
  display_name: string
  avatar_url: string | null
  sort_order: number
}

interface Client {
  id: string
  first_name: string
  last_name: string | null
  email: string | null
}

interface NewProjectFormProps {
  artists: Artist[]
  clients: Client[]
  studioId?: string
}

interface DraftState {
  clientId: string | null
  primaryArtistId: string | null
  secondaryArtistIds: string[]
  name: string
  description: string
  placement: string
  placementOther: string
  styles: string[]
  size: ProjectSize | ''
  colorMode: ProjectColorMode | ''
  totalSessionsPlanned: string
  totalPriceCents: number
  initialDepositCents: number
  depositApplyRule: DepositApplyRule
  referenceNotes: string
  pendingReferenceUrls: string[]
}

const EMPTY_DRAFT: DraftState = {
  clientId: null,
  primaryArtistId: null,
  secondaryArtistIds: [],
  name: '',
  description: '',
  placement: '',
  placementOther: '',
  styles: [],
  size: '',
  colorMode: '',
  totalSessionsPlanned: '',
  totalPriceCents: 0,
  initialDepositCents: 0,
  depositApplyRule: 'last_session',
  referenceNotes: '',
  pendingReferenceUrls: [],
}

// ─── Placement Combobox ───────────────────────────────────────────────────────

function PlacementField({
  value,
  onChange,
}: {
  value: string
  onChange: (v: string) => void
}) {
  const [isOther, setIsOther] = useState(
    () => value.length > 0 && !PLACEMENT_PRESETS.includes(value as typeof PLACEMENT_PRESETS[number])
  )

  const presetOptions: ComboBoxOption[] = [
    ...PLACEMENT_PRESETS.map((p) => ({ value: p, label: p })),
    { value: '__other__', label: 'Other…' },
  ]

  const handlePresetChange = (v: string | null) => {
    if (v === '__other__') {
      setIsOther(true)
      onChange('')
    } else {
      setIsOther(false)
      onChange(v ?? '')
    }
  }

  const presetValue = isOther ? '__other__' : (value || null)

  return (
    <div className="space-y-2">
      <ComboBox
        options={presetOptions}
        value={presetValue}
        onValueChange={handlePresetChange}
        placeholder="Select placement…"
        searchPlaceholder="Search or type…"
      />
      {isOther && (
        <Input
          placeholder="Describe placement…"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          maxLength={100}
          autoFocus
        />
      )}
    </div>
  )
}

// ─── Style Multi-Select ────────────────────────────────────────────────────────

function StyleMultiSelect({
  selected,
  onChange,
}: {
  selected: string[]
  onChange: (v: string[]) => void
}) {
  const toggle = (style: string) => {
    if (selected.includes(style)) {
      onChange(selected.filter((s) => s !== style))
    } else {
      onChange([...selected, style])
    }
  }

  return (
    <div className="flex flex-wrap gap-2">
      {PROJECT_STYLES.map((s) => {
        const active = selected.includes(s)
        return (
          <button
            key={s}
            type="button"
            onClick={() => toggle(s)}
            className={cn(
              'inline-flex items-center gap-1 rounded-full border px-3 py-1 text-xs font-medium transition-colors',
              active
                ? 'border-foreground bg-foreground text-background'
                : 'border-border bg-background text-muted-foreground hover:border-foreground/40 hover:text-foreground'
            )}
          >
            {active && <Check className="size-3" aria-hidden="true" />}
            {STYLE_LABELS[s] ?? s}
          </button>
        )
      })}
    </div>
  )
}

// ─── Color Mode Segmented Control ─────────────────────────────────────────────

function ColorModeControl({
  value,
  onChange,
}: {
  value: ProjectColorMode | ''
  onChange: (v: ProjectColorMode | '') => void
}) {
  return (
    <div className="flex rounded-lg border border-border overflow-hidden">
      {PROJECT_COLOR_MODE_VALUES.map((mode, idx) => (
        <button
          key={mode}
          type="button"
          onClick={() => onChange(value === mode ? '' : mode)}
          className={cn(
            'flex-1 py-2 text-xs font-medium transition-colors',
            idx > 0 && 'border-l border-border',
            value === mode
              ? 'bg-foreground text-background'
              : 'bg-background text-muted-foreground hover:text-foreground hover:bg-muted/40'
          )}
        >
          {COLOR_MODE_LABELS[mode]}
        </button>
      ))}
    </div>
  )
}

// ─── Quick Create Client Dialog ────────────────────────────────────────────────

function QuickCreateClientDialog({
  open,
  onOpenChange,
  onCreated,
}: {
  open: boolean
  onOpenChange: (v: boolean) => void
  onCreated: (id: string, label: string, email: string | null) => void
}) {
  const [isPending, startTransition] = useTransition()
  const [firstName, setFirstName] = useState('')
  const [lastName, setLastName] = useState('')
  const [phone, setPhone] = useState('')
  const [email, setEmail] = useState('')
  const [error, setError] = useState<string | null>(null)

  const reset = () => {
    setFirstName('')
    setLastName('')
    setPhone('')
    setEmail('')
    setError(null)
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    if (!firstName.trim()) {
      setError('First name is required')
      return
    }

    const fd = new FormData()
    fd.set('firstName', firstName.trim())
    if (lastName.trim()) fd.set('lastName', lastName.trim())
    if (phone.trim()) fd.set('phone', phone.trim())
    if (email.trim()) fd.set('email', email.trim())

    startTransition(async () => {
      const result = await quickCreateClientAction(fd)
      if (!result.ok) {
        setError(result.error)
        return
      }
      toast.success(`${result.data.label} added`)
      onCreated(result.data.id, result.data.label, result.data.email)
      reset()
      onOpenChange(false)
    })
  }

  return (
    <Dialog open={open} onOpenChange={(v) => { if (!isPending) { reset(); onOpenChange(v) } }}>
      <DialogContent className="sm:max-w-sm">
        <DialogHeader>
          <DialogTitle>New client</DialogTitle>
          <DialogDescription>
            Minimum details. Full profile at /clients/new.
          </DialogDescription>
        </DialogHeader>
        <form id="quick-client-form" onSubmit={handleSubmit} className="space-y-3">
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label htmlFor="qc-first-name">
                First name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="qc-first-name"
                value={firstName}
                onChange={(e) => setFirstName(e.target.value)}
                maxLength={100}
                autoFocus
                disabled={isPending}
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="qc-last-name">Last name</Label>
              <Input
                id="qc-last-name"
                value={lastName}
                onChange={(e) => setLastName(e.target.value)}
                maxLength={100}
                disabled={isPending}
              />
            </div>
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="qc-phone">Phone</Label>
            <Input
              id="qc-phone"
              type="tel"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              maxLength={30}
              disabled={isPending}
            />
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="qc-email">Email</Label>
            <Input
              id="qc-email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              disabled={isPending}
            />
          </div>
          {error && <p className="text-xs text-destructive">{error}</p>}
        </form>
        <DialogFooter>
          <Button
            type="button"
            variant="outline"
            onClick={() => { reset(); onOpenChange(false) }}
            disabled={isPending}
          >
            Cancel
          </Button>
          <Button type="submit" form="quick-client-form" disabled={isPending}>
            {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Create client
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

// ─── Moodboard Upload Panel ────────────────────────────────────────────────────

function MoodboardPanel({
  pendingReferenceUrls,
  onUrlsChange,
  pendingFiles,
  onFilesChange,
}: {
  pendingReferenceUrls: string[]
  onUrlsChange: (urls: string[]) => void
  pendingFiles: File[]
  onFilesChange: (files: File[]) => void
}) {
  const [urlInput, setUrlInput] = useState('')
  const [urlError, setUrlError] = useState<string | null>(null)

  const detectSource = (url: string): string => {
    if (url.includes('pinterest')) return 'pinterest'
    if (url.includes('instagram')) return 'instagram'
    if (url.includes('behance')) return 'behance'
    return 'external'
  }

  const addUrl = () => {
    const trimmed = urlInput.trim()
    if (!trimmed) return
    try {
      new URL(trimmed)
    } catch {
      setUrlError('Enter a valid URL')
      return
    }
    setUrlError(null)
    onUrlsChange([...pendingReferenceUrls, trimmed])
    setUrlInput('')
  }

  const removeUrl = (idx: number) => {
    onUrlsChange(pendingReferenceUrls.filter((_, i) => i !== idx))
  }

  const handleFiles = (files: File[]) => {
    onFilesChange([...pendingFiles, ...files])
  }

  const removeFile = (idx: number) => {
    onFilesChange(pendingFiles.filter((_, i) => i !== idx))
  }

  return (
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
      {/* Upload images */}
      <div className="space-y-2">
        <p className="text-xs font-semibold text-foreground uppercase tracking-wide">Upload images</p>
        <FileDropzone
          accept={IMAGE_ACCEPT}
          maxSize={10 * 1024 * 1024}
          maxFiles={10}
          onFilesAccepted={handleFiles}
          className="min-h-[100px]"
        />
        {pendingFiles.length > 0 && (
          <ul className="space-y-1">
            {pendingFiles.map((f, i) => (
              <li key={i} className="flex items-center gap-2 text-xs text-muted-foreground">
                <span className="truncate flex-1">{f.name}</span>
                <button
                  type="button"
                  onClick={() => removeFile(i)}
                  className="shrink-0 text-muted-foreground hover:text-foreground"
                  aria-label={`Remove ${f.name}`}
                >
                  <X className="size-3" aria-hidden="true" />
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Paste URL */}
      <div className="space-y-2">
        <p className="text-xs font-semibold text-foreground uppercase tracking-wide">Paste URL</p>
        <p className="text-xs text-muted-foreground">Pinterest · Instagram · Behance</p>
        <div className="flex gap-2">
          <Input
            placeholder="https://pinterest.com/…"
            value={urlInput}
            onChange={(e) => { setUrlInput(e.target.value); setUrlError(null) }}
            onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addUrl() } }}
            className="flex-1 text-xs"
          />
          <Button type="button" variant="outline" size="sm" onClick={addUrl}>
            Add
          </Button>
        </div>
        {urlError && <p className="text-xs text-destructive">{urlError}</p>}
        {pendingReferenceUrls.length > 0 && (
          <ul className="space-y-1">
            {pendingReferenceUrls.map((url, i) => (
              <li key={i} className="flex items-center gap-1.5 text-xs">
                <span className="rounded bg-muted px-1.5 py-0.5 text-muted-foreground uppercase text-[10px]">
                  {detectSource(url)}
                </span>
                <span className="truncate flex-1 text-muted-foreground">{url}</span>
                <button
                  type="button"
                  onClick={() => removeUrl(i)}
                  className="shrink-0 text-muted-foreground hover:text-foreground"
                  aria-label="Remove URL"
                >
                  <X className="size-3" aria-hidden="true" />
                </button>
              </li>
            ))}
          </ul>
        )}
        {/* TODO: thumbnail OG-scrape for URL previews (v2 — needs server-side oembed) */}
      </div>

      {/* Flash designs */}
      <div className="space-y-2">
        <p className="text-xs font-semibold text-foreground uppercase tracking-wide">Flash designs</p>
        {/* TODO: Flash library not yet available (flash_designs table pending Dato sprint) */}
        <button
          type="button"
          disabled
          className="w-full flex items-center justify-center gap-2 rounded-xl border-2 border-dashed border-border bg-muted/20 px-4 py-6 text-xs text-muted-foreground cursor-not-allowed opacity-60"
          title="Flash library coming soon"
        >
          <Plus className="size-4" aria-hidden="true" />
          Link flash design
          <span className="rounded bg-muted px-1.5 py-0.5 text-[10px] uppercase">soon</span>
        </button>
      </div>
    </div>
  )
}

// ─── Main Form ────────────────────────────────────────────────────────────────

export function NewProjectForm({ artists, clients: initialClients, studioId }: NewProjectFormProps) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [showQuickCreate, setShowQuickCreate] = useState(false)
  const [submitMode, setSubmitMode] = useState<'create' | 'create_book'>('create')
  const [hasDraft, setHasDraft] = useState(false)

  // Extended client list (quick-created clients prepended)
  const [extraClients, setExtraClients] = useState<Client[]>([])
  const allClients = useMemo(() => [...extraClients, ...initialClients], [extraClients, initialClients])

  // ── Form state ────────────────────────────────────────────────────────────
  const [clientId, setClientId] = useState<string | null>(null)
  const [primaryArtistId, setPrimaryArtistId] = useState<string | null>(null)
  const [secondaryArtistIds, setSecondaryArtistIds] = useState<string[]>([])
  const [name, setName] = useState('')
  const [description, setDescription] = useState('')
  const [placement, setPlacement] = useState('')
  const [styles, setStyles] = useState<string[]>([])
  const [size, setSize] = useState<ProjectSize | ''>('')
  const [colorMode, setColorMode] = useState<ProjectColorMode | ''>('')
  const [totalSessionsPlanned, setTotalSessionsPlanned] = useState('')
  const [totalPriceCents, setTotalPriceCents] = useState(0)
  const [initialDepositCents, setInitialDepositCents] = useState(0)
  const [depositApplyRule, setDepositApplyRule] = useState<DepositApplyRule>('last_session')
  const [requestDeposit, setRequestDeposit] = useState(false)
  const [pendingReferenceUrls, setPendingReferenceUrls] = useState<string[]>([])
  const [pendingFiles, setPendingFiles] = useState<File[]>([])
  const [referenceNotes, setReferenceNotes] = useState('')

  // ── Draft auto-save ───────────────────────────────────────────────────────
  const draftKey = studioId ? `${DRAFT_KEY_PREFIX}${studioId}` : null
  const draftTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const isDraftRestoredRef = useRef(false)

  const collectDraft = useCallback((): DraftState => ({
    clientId,
    primaryArtistId,
    secondaryArtistIds,
    name,
    description,
    placement,
    placementOther: '',
    styles,
    size,
    colorMode,
    totalSessionsPlanned,
    totalPriceCents,
    initialDepositCents,
    depositApplyRule,
    referenceNotes,
    pendingReferenceUrls,
  }), [clientId, primaryArtistId, secondaryArtistIds, name, description, placement, styles, size, colorMode, totalSessionsPlanned, totalPriceCents, initialDepositCents, depositApplyRule, referenceNotes, pendingReferenceUrls])

  // On mount: check for existing draft
  useEffect(() => {
    if (!draftKey || isDraftRestoredRef.current) return
    try {
      const raw = localStorage.getItem(draftKey)
      if (raw) {
        const saved = JSON.parse(raw) as Partial<DraftState>
        setHasDraft(true)
        isDraftRestoredRef.current = true
        // Store but don't auto-restore — show the indicator, let user decide
        isDraftRestoredRef.current = false
        void saved // reference to prevent lint warning
      }
    } catch {
      // ignore parse errors
    }
  }, [draftKey])

  const restoreDraft = () => {
    if (!draftKey) return
    try {
      const raw = localStorage.getItem(draftKey)
      if (!raw) return
      const saved = JSON.parse(raw) as Partial<DraftState>
      if (saved.clientId !== undefined) setClientId(saved.clientId)
      if (saved.primaryArtistId !== undefined) setPrimaryArtistId(saved.primaryArtistId)
      if (saved.secondaryArtistIds) setSecondaryArtistIds(saved.secondaryArtistIds)
      if (saved.name !== undefined) setName(saved.name)
      if (saved.description !== undefined) setDescription(saved.description)
      if (saved.placement !== undefined) setPlacement(saved.placement)
      if (saved.styles) setStyles(saved.styles)
      if (saved.size !== undefined) setSize(saved.size ?? '')
      if (saved.colorMode !== undefined) setColorMode(saved.colorMode ?? '')
      if (saved.totalSessionsPlanned !== undefined) setTotalSessionsPlanned(saved.totalSessionsPlanned)
      if (saved.totalPriceCents !== undefined) setTotalPriceCents(saved.totalPriceCents)
      if (saved.initialDepositCents !== undefined) setInitialDepositCents(saved.initialDepositCents)
      if (saved.depositApplyRule) setDepositApplyRule(saved.depositApplyRule)
      if (saved.referenceNotes !== undefined) setReferenceNotes(saved.referenceNotes)
      if (saved.pendingReferenceUrls) setPendingReferenceUrls(saved.pendingReferenceUrls)
      setHasDraft(false)
    } catch {
      // ignore
    }
  }

  const clearDraft = () => {
    if (draftKey) localStorage.removeItem(draftKey)
    setHasDraft(false)
  }

  // Auto-save every 3s on field changes
  useEffect(() => {
    if (!draftKey) return
    if (draftTimerRef.current) clearTimeout(draftTimerRef.current)
    draftTimerRef.current = setTimeout(() => {
      try {
        localStorage.setItem(draftKey, JSON.stringify(collectDraft()))
      } catch {
        // ignore quota errors
      }
    }, 3000)
    return () => {
      if (draftTimerRef.current) clearTimeout(draftTimerRef.current)
    }
  }, [draftKey, collectDraft])

  // ── Derived values ────────────────────────────────────────────────────────
  const totalSessions = totalSessionsPlanned ? parseInt(totalSessionsPlanned, 10) : null
  const perSessionCents =
    totalSessions && totalSessions > 0 && totalPriceCents > 0
      ? Math.round(totalPriceCents / totalSessions)
      : null

  const formatMoney = (cents: number) =>
    new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100)

  // ── Options ───────────────────────────────────────────────────────────────
  const clientOptions: ComboBoxOption[] = useMemo(
    () =>
      allClients.map((c) => {
        const opt: ComboBoxOption = {
          value: c.id,
          label: `${c.first_name}${c.last_name ? ` ${c.last_name}` : ''}`,
        }
        if (c.email) opt.description = c.email
        return opt
      }),
    [allClients]
  )

  const artistOptions: ComboBoxOption[] = useMemo(
    () =>
      artists.map((a) => ({
        value: a.id,
        label: a.display_name,
      })),
    [artists]
  )

  const secondaryArtistOptions: ComboBoxOption[] = useMemo(
    () =>
      artists
        .filter((a) => a.id !== primaryArtistId)
        .map((a) => ({
          value: a.id,
          label: a.display_name,
        })),
    [artists, primaryArtistId]
  )

  const addSecondaryArtist = (id: string | null) => {
    if (!id || secondaryArtistIds.includes(id)) return
    setSecondaryArtistIds([...secondaryArtistIds, id])
  }

  const removeSecondaryArtist = (id: string) => {
    setSecondaryArtistIds(secondaryArtistIds.filter((a) => a !== id))
  }

  // ── Submit ────────────────────────────────────────────────────────────────
  const handleSubmit = (mode: 'create' | 'create_book') => {
    setErrors({})

    if (!clientId) {
      setErrors({ clientId: 'Please select a client' })
      return
    }
    if (!name.trim()) {
      setErrors({ name: 'Project name is required' })
      return
    }

    const fd = new FormData()
    fd.set('clientId', clientId)
    fd.set('name', name.trim())
    if (description) fd.set('description', description)
    if (placement) fd.set('placement', placement)
    // v1: store first selected style as primary; scaffold multi-select UI
    // TODO: migrate projects.style to text[] for full multi-select persistence
    if (styles.length > 0) fd.set('style', styles[0] ?? '')
    if (primaryArtistId) fd.set('primaryArtistId', primaryArtistId)
    secondaryArtistIds.forEach((id) => fd.append('secondaryArtistIds[]', id))
    if (totalSessionsPlanned) fd.set('totalSessionsPlanned', totalSessionsPlanned)
    fd.set('totalPriceCents', String(totalPriceCents))
    if (initialDepositCents > 0) fd.set('initialDepositCents', String(initialDepositCents))
    fd.set('depositApplyRule', depositApplyRule)
    if (requestDeposit) fd.set('requestDeposit', 'true')
    if (size) fd.set('size', size)
    if (colorMode) fd.set('colorMode', colorMode)
    if (referenceNotes) fd.set('referenceNotes', referenceNotes)
    pendingReferenceUrls.forEach((url) => fd.append('pendingReferenceUrls[]', url))

    startTransition(async () => {
      const result = await createProjectAction(fd)
      if (!result.ok) {
        toast.error(result.error)
        return
      }

      const projectId = result.data.id

      // Upload any pending reference images
      if (pendingFiles.length > 0) {
        await Promise.allSettled(
          pendingFiles.map(async (file, idx) => {
            const imageFormData = new FormData()
            imageFormData.set('file', file)
            imageFormData.set('displayOrder', String(idx))
            const uploadResult = await addReferenceAction(projectId, imageFormData)
            if (!uploadResult.ok) {
              logger.error({ error: uploadResult.error, projectId }, 'Reference upload failed')
            }
          })
        )
      }

      // TODO: if requestDeposit=true, trigger sendDepositReminderAction from the
      // deposit reminder flow (Inbox integration, Sprint N). Scaffold only for now.
      if (requestDeposit) {
        logger.info({ projectId }, 'requestDeposit=true — reminder flow scaffold (not yet wired)')
      }

      clearDraft()
      toast.success('Project created')

      if (mode === 'create_book') {
        // Pass project_id as query param; appointment wizard picks it up
        // If AppointmentWizardClient doesn't accept query param yet, use sessionStorage
        try {
          sessionStorage.setItem('inkos:new-appointment-project-id', projectId)
        } catch {
          // ignore if sessionStorage unavailable
        }
        router.push(`/bookings/new?project_id=${projectId}`)
      } else {
        router.push(`/projects/${projectId}`)
      }
    })
  }

  const handleFormSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()
    handleSubmit(submitMode)
  }

  // ─── Render ───────────────────────────────────────────────────────────────

  return (
    <>
      <QuickCreateClientDialog
        open={showQuickCreate}
        onOpenChange={setShowQuickCreate}
        onCreated={(id, label, email) => {
          setExtraClients((prev) => [{ id, first_name: label.split(' ')[0] ?? label, last_name: label.split(' ').slice(1).join(' ') || null, email }, ...prev])
          setClientId(id)
        }}
      />

      <form onSubmit={handleFormSubmit} className="space-y-4">
        {/* Draft banner */}
        {hasDraft && (
          <div className="flex items-center gap-3 rounded-lg border border-border bg-muted/30 px-4 py-3 text-sm">
            <Info className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
            <span className="text-muted-foreground">Draft auto-saved.</span>
            <button
              type="button"
              onClick={restoreDraft}
              className="ml-auto text-foreground underline underline-offset-2 hover:no-underline text-xs font-medium"
            >
              Restore
            </button>
            <button
              type="button"
              onClick={clearDraft}
              className="text-muted-foreground hover:text-foreground text-xs"
            >
              Dismiss
            </button>
          </div>
        )}

        {/* ── Card 1: Client & Basics ─────────────────────────────────────── */}
        <Card className="shadow-[var(--shadow-card)]">
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Client & Basics</CardTitle>
            <CardDescription className="text-sm">Who is this project for?</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Client */}
            <div className="space-y-1.5">
              <Label htmlFor="client-select">
                Client <span className="text-destructive">*</span>
              </Label>
              {/* Client combobox with inline "+ Create new client" footer */}
              <div className="relative">
                <ComboBox
                  options={[
                    ...clientOptions,
                    { value: '__create__', label: '+ Create new client' },
                  ]}
                  value={clientId}
                  onValueChange={(v) => {
                    if (v === '__create__') {
                      setShowQuickCreate(true)
                    } else {
                      setClientId(v)
                    }
                  }}
                  placeholder="Search clients…"
                  searchPlaceholder="Type to search…"
                />
              </div>
              {errors.clientId && (
                <p className="text-xs text-destructive">{errors.clientId}</p>
              )}
            </div>

            {/* Project name */}
            <div className="space-y-1.5">
              <Label htmlFor="project-name">
                Project name <span className="text-destructive">*</span>
              </Label>
              <Input
                id="project-name"
                placeholder="e.g. Dragon Sleeve"
                value={name}
                onChange={(e) => setName(e.target.value)}
                maxLength={200}
              />
              <p className="text-xs text-muted-foreground">
                Short name you&apos;ll see often. Client can see this too.
              </p>
              {errors.name && <p className="text-xs text-destructive">{errors.name}</p>}
            </div>

            {/* Description */}
            <div className="space-y-1.5">
              <Label htmlFor="project-description">Description</Label>
              <Textarea
                id="project-description"
                placeholder="Brief description of the project…"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                rows={3}
                maxLength={2000}
                className="resize-none"
              />
            </div>

            {/* Placement */}
            <div className="space-y-1.5">
              <Label>Placement</Label>
              <PlacementField value={placement} onChange={setPlacement} />
            </div>
          </CardContent>
        </Card>

        {/* ── Card 2: Style & Design ──────────────────────────────────────── */}
        <Card className="shadow-[var(--shadow-card)]">
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Style & Design</CardTitle>
            <CardDescription className="text-sm">
              Defines the artistic direction. Multi-select.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-5">
            {/* Style multi-select */}
            <div className="space-y-2">
              <Label>Style</Label>
              <StyleMultiSelect selected={styles} onChange={setStyles} />
              {styles.length > 1 && (
                <p className="text-xs text-muted-foreground">
                  Primary style: <span className="font-medium text-foreground">{STYLE_LABELS[styles[0] ?? ''] ?? styles[0]}</span>.
                  {/* TODO: migrate projects.style column to text[] to persist all selected styles */}
                  {' '}Additional styles saved in v2 after DB migration to text[].
                </p>
              )}
            </div>

            {/* Size */}
            <div className="space-y-1.5">
              <Label>Size</Label>
              <Select value={size || undefined} onValueChange={(v) => setSize(v ? v as ProjectSize : '')}>
                <SelectTrigger>
                  <SelectValue placeholder="Select size…" />
                </SelectTrigger>
                <SelectContent>
                  {PROJECT_SIZE_VALUES.map((s) => (
                    <SelectItem key={s} value={s}>
                      {SIZE_LABELS[s]}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Color mode */}
            <div className="space-y-1.5">
              <Label>Color / B&G</Label>
              <ColorModeControl value={colorMode} onChange={setColorMode} />
            </div>
          </CardContent>
        </Card>

        {/* ── Card 3: Team ────────────────────────────────────────────────── */}
        <Card className="shadow-[var(--shadow-card)]">
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Team</CardTitle>
            <CardDescription className="text-sm">Primary and collaborating artists.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Primary artist */}
            <div className="space-y-1.5">
              <Label>Primary artist</Label>
              <ComboBox
                options={artistOptions}
                value={primaryArtistId}
                onValueChange={setPrimaryArtistId}
                placeholder="Assign artist…"
                searchPlaceholder="Search artists…"
              />
            </div>

            {/* Secondary artists */}
            <div className="space-y-1.5">
              <Label>Secondary artists</Label>
              <ComboBox
                options={secondaryArtistOptions.filter((o) => !secondaryArtistIds.includes(o.value))}
                value={null}
                onValueChange={(v) => { if (v) addSecondaryArtist(v) }}
                placeholder="Add collaborator…"
                searchPlaceholder="Search artists…"
              />
              {secondaryArtistIds.length > 0 && (
                <div className="flex flex-wrap gap-2 mt-2">
                  {secondaryArtistIds.map((id) => {
                    const artist = artists.find((a) => a.id === id)
                    return (
                      <Badge key={id} variant="secondary" className="gap-1.5 pr-1">
                        {artist?.display_name ?? id}
                        <button
                          type="button"
                          onClick={() => removeSecondaryArtist(id)}
                          className="ml-0.5 rounded hover:text-destructive"
                          aria-label={`Remove ${artist?.display_name ?? 'artist'}`}
                        >
                          <X className="size-3" aria-hidden="true" />
                        </button>
                      </Badge>
                    )
                  })}
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* ── Card 4: Sessions & Pricing ───────────────────────────────────── */}
        <Card className="shadow-[var(--shadow-card)]">
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Sessions & Pricing</CardTitle>
            <CardDescription className="text-sm">
              Plan, track, and split the project cost.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Sessions planned */}
            <div className="space-y-1.5">
              <Label htmlFor="sessions-planned">Total sessions planned</Label>
              <Input
                id="sessions-planned"
                type="number"
                placeholder="Leave blank for open-ended"
                value={totalSessionsPlanned}
                onChange={(e) => setTotalSessionsPlanned(e.target.value)}
                min={1}
                max={50}
              />
            </div>

            {/* Total price */}
            <div className="space-y-1.5">
              <Label>Total price</Label>
              <MoneyInput
                value={totalPriceCents}
                onValueChange={(v) => setTotalPriceCents(v ?? 0)}
                placeholder="0.00"
              />
              <p className="text-xs text-muted-foreground">
                Roll-up price across all sessions. You can also set per-session prices when booking each session.
              </p>
              {perSessionCents !== null && (
                <p className="text-xs text-muted-foreground tabular-nums">
                  ≈ {formatMoney(perSessionCents)}/session
                </p>
              )}
            </div>

            {/* Initial deposit */}
            <div className="space-y-1.5">
              <Label>Initial deposit (optional)</Label>
              <MoneyInput
                value={initialDepositCents}
                onValueChange={(v) => setInitialDepositCents(v ?? 0)}
                placeholder="0.00"
              />
              <p className="text-xs text-muted-foreground">
                Records a deposit already received into the project pool.
              </p>
            </div>

            {/* Deposit apply rule */}
            {initialDepositCents > 0 && (
              <div className="space-y-2">
                <Label>Apply deposit to</Label>
                <RadioGroup
                  value={depositApplyRule}
                  onValueChange={(v) => { if (v !== null) setDepositApplyRule(v as DepositApplyRule) }}
                >
                  {DEPOSIT_APPLY_RULE_VALUES.map((rule) => (
                    <label
                      key={rule}
                      className="flex items-start gap-3 cursor-pointer rounded-lg border border-border p-3 hover:bg-muted/30 has-[[data-slot=radio-group-item][data-checked]]:border-foreground"
                    >
                      <RadioGroupItem value={rule} className="mt-0.5" />
                      <div>
                        <p className="text-sm font-medium">{DEPOSIT_RULE_LABELS[rule].label}</p>
                        <p className="text-xs text-muted-foreground">{DEPOSIT_RULE_LABELS[rule].desc}</p>
                      </div>
                    </label>
                  ))}
                </RadioGroup>
              </div>
            )}

            {/* Request deposit toggle */}
            <div className="flex items-center justify-between rounded-lg border border-border px-4 py-3">
              <div>
                <p className="text-sm font-medium">Request deposit from client</p>
                <p className="text-xs text-muted-foreground">
                  Send a deposit reminder via Inbox.
                  {/* TODO: wire to sendDepositReminderAction from the Inbox deposit reminder flow */}
                </p>
              </div>
              <Switch
                checked={requestDeposit}
                onCheckedChange={setRequestDeposit}
                aria-label="Request deposit from client"
              />
            </div>
          </CardContent>
        </Card>

        {/* ── Card 5: Moodboard & References ──────────────────────────────── */}
        <Card className="shadow-[var(--shadow-card)]">
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Moodboard</CardTitle>
            <CardDescription className="text-sm">
              Images, inspiration links, and flash designs.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <MoodboardPanel
              pendingReferenceUrls={pendingReferenceUrls}
              onUrlsChange={setPendingReferenceUrls}
              pendingFiles={pendingFiles}
              onFilesChange={setPendingFiles}
            />

            {/* Reference notes */}
            <div className="space-y-1.5">
              <Label htmlFor="reference-notes">Reference notes</Label>
              <Textarea
                id="reference-notes"
                placeholder="Inspiration notes, tone, specific elements to include/avoid. Artists read this before every session."
                value={referenceNotes}
                onChange={(e) => setReferenceNotes(e.target.value)}
                rows={3}
                maxLength={5000}
                className="resize-none"
              />
            </div>
          </CardContent>
        </Card>

        {/* ── Actions ─────────────────────────────────────────────────────── */}
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={() => { clearDraft(); router.back() }}
              disabled={isPending}
            >
              Cancel
            </Button>
            {/* Draft indicator — subtle, next to Cancel */}
            {draftKey && (
              <span className="text-xs text-muted-foreground select-none">
                Draft auto-saved
              </span>
            )}
          </div>

          {/* Split CTA */}
          <div className="flex items-center rounded-lg overflow-hidden border border-foreground">
            {/* Left: Create Project */}
            <Button
              type="submit"
              onClick={() => setSubmitMode('create')}
              disabled={isPending}
              className="rounded-none border-0 border-r border-background/20 px-5"
            >
              {isPending && submitMode === 'create' && (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              )}
              Create project
            </Button>
            {/* Right: Create & book first session */}
            <Button
              type="submit"
              onClick={() => setSubmitMode('create_book')}
              disabled={isPending}
              className="rounded-none border-0 px-4 bg-foreground/90 hover:bg-foreground/80"
            >
              {isPending && submitMode === 'create_book' ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <ArrowRight className="h-4 w-4" />
              )}
              <span className="sr-only">Create &amp; book first session</span>
            </Button>
          </div>
        </div>

        {/* Accessible label for split CTA */}
        <p className="text-xs text-muted-foreground text-right">
          Arrow button: Create project and book the first session.
        </p>
      </form>
    </>
  )
}

