// The Supabase client infers a partial type from the explicit select() columns.
// We spread the row and cast to ProjectListItem — the select string above
// includes all required columns so the cast is safe. The Wave-1 columns
// (size, color_mode, deposit_apply_rule, secondary_artist_ids, reference_notes)
// are now explicitly listed in the select string.
let rows = (data ?? []).map((p) => {
  const row = p as unknown as Record<string, unknown>
  return {
    ...p,
    client: Array.isArray(p.client) ? (p.client[0] ?? null) : (p.client ?? null),
    primary_artist: Array.isArray(p.primary_artist) ? (p.primary_artist[0] ?? null) : (p.primary_artist ?? null),
    sessions_completed: sessionCounts[p.id] ?? 0,
    deposit_balance: Math.max(0, p.deposit_pool_cents - p.deposit_applied_cents),
    stalled_at: row['stalled_at'] as string | null ?? null,
    size: (row['size'] ?? null) as ProjectListItem['size'],
    color_mode: (row['color_mode'] ?? null) as ProjectListItem['color_mode'],
    deposit_apply_rule: (row['deposit_apply_rule'] ?? 'last_session') as ProjectListItem['deposit_apply_rule'],
    secondary_artist_ids: (row['secondary_artist_ids'] ?? []) as string[],
    reference_notes: (row['reference_notes'] ?? null) as string | null,
  } as ProjectListItem
})

